import { NextRequest, NextResponse } from 'next/server';
import { db } from '@/lib/db';
import { cache, CacheTTL } from '@/lib/cache';

export const dynamic = 'force-dynamic';


// GET all active loans (both online and offline) with complete passbook data
export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const filter = searchParams.get('filter') || 'all'; // 'all', 'online', 'offline'
    const includePassbook = searchParams.get('passbook') === 'true';

    // Generate cache key
    const cacheKey = `active-loans:${filter}:${includePassbook}`;
    const noCache = searchParams.get('noCache') === 'true';

    // Check cache first — skip when noCache=true (e.g. right after a new loan is created)
    if (!includePassbook && !noCache) {
      const cached = cache.get(cacheKey);
      if (cached) {
        return NextResponse.json({ ...cached, cached: true });
      }
    }

    // Bust cache immediately when noCache requested, so no subsequent call gets stale data
    if (noCache) {
      cache.delete(cacheKey);
    }

    let onlineLoans: any[] = [];
    let offlineLoans: any[] = [];

    // Remove production console.log — fires on every request
    // console.log('[all-active] Fetching active loans with filter:', filter);

    // Define allowed statuses for offline loans
    const activeOfflineStatuses = [
      'ACTIVE',
      'INTEREST_ONLY'
    ] as any[];

    // Fetch online loans (from LoanApplication)
    if (filter === 'all' || filter === 'online') {
      // ── Build online include options ──────────────────────────────────────
      const onlineInclude: any = {
        customer:    { select: { id: true, name: true, email: true, phone: true } },
        company:     { select: { id: true, name: true, code: true } },
        sessionForm: { select: { approvedAmount: true, interestRate: true, tenure: true, emiAmount: true, totalAmount: true, totalInterest: true } },
      };

      if (includePassbook) {
        // Full EMI list only for passbook view
        onlineInclude.emiSchedules = {
          orderBy: { installmentNumber: 'asc' },
          select: {
            id: true, installmentNumber: true, dueDate: true, originalDueDate: true,
            principalAmount: true, interestAmount: true, totalAmount: true,
            paidAmount: true, paidPrincipal: true, paidInterest: true,
            paymentStatus: true, paidDate: true, paymentMode: true,
            penaltyAmount: true, daysOverdue: true
          }
        };
        onlineInclude.payments = {
          where: { status: 'COMPLETED' },
          orderBy: { createdAt: 'desc' },
          select: { id: true, amount: true, paymentMode: true, createdAt: true, status: true, receiptNumber: true }
        };
      } else {
        // List mode: only next pending/overdue EMI (massive bandwidth saving)
        onlineInclude.emiSchedules = {
          where: { paymentStatus: { in: ['PENDING', 'OVERDUE', 'PARTIALLY_PAID'] } },
          orderBy: { installmentNumber: 'asc' },
          take: 1,
          select: {
            id: true, installmentNumber: true, dueDate: true,
            totalAmount: true, paidAmount: true, paymentStatus: true,
            penaltyAmount: true, daysOverdue: true, isPartialPayment: true,
            isInterestOnly: true, nextPaymentDate: true
          }
        };
      }

      onlineLoans = await db.loanApplication.findMany({
        where: { status: { in: ['ACTIVE', 'ACTIVE_INTEREST_ONLY', 'DISBURSED'] }, isMirrorLoan: false },
        orderBy: { createdAt: 'desc' },
        include: onlineInclude,
        take: 300, // Hard cap — prevents loading 1000+ loans into RAM
      });
    }

    // ── Offline loans include options ──────────────────────────────────────
    const offlineInclude: any = {
      customer: { select: { id: true, name: true, email: true, phone: true } },
      company:  { select: { id: true, name: true, code: true } },
      createdBy: { select: { id: true, name: true, role: true } },
    };

    if (includePassbook) {
      offlineInclude.emis = {
        orderBy: { installmentNumber: 'asc' },
        select: {
          id: true, installmentNumber: true, dueDate: true,
          principalAmount: true, interestAmount: true, totalAmount: true,
          paidAmount: true, paymentStatus: true, paidDate: true,
          paymentMode: true, penaltyAmount: true
        }
      };
    } else {
      // List mode: only next pending EMI
      offlineInclude.emis = {
        where: { paymentStatus: { in: ['PENDING', 'OVERDUE', 'PARTIALLY_PAID'] } },
        orderBy: { installmentNumber: 'asc' },
        take: 1,
        select: {
          id: true, installmentNumber: true, dueDate: true,
          totalAmount: true, paidAmount: true, paymentStatus: true,
          penaltyAmount: true, daysOverdue: true
        }
      };
    }

    // Fetch offline loans — exclude mirror loans (internal accounting duplicates)
    if (filter === 'all' || filter === 'offline') {
      offlineLoans = await db.offlineLoan.findMany({
        where: { status: { in: activeOfflineStatuses }, isMirrorLoan: false },
        orderBy: { createdAt: 'desc' },
        include: offlineInclude,
        take: 300, // Hard cap
      });
    }

    // Get all mirror loan mappings to identify mirror loans
    let mirrorLoanMappings: any[] = [];
    // Lookup maps for mirror loan details (populated after mirrorLoanMappings is fetched)
    let onlineMirrorLoanMap = new Map<string, any>();
    let offlineMirrorLoanMap = new Map<string, any>();
    const onlineOutstandingMap = new Map<string, number>();
    const offlineOutstandingMap = new Map<string, number>();
    const allLoanIds = [
      ...onlineLoans.map(l => l.id),
      ...offlineLoans.map(l => l.id)
    ];
    
    if (allLoanIds.length > 0) {
      mirrorLoanMappings = await db.mirrorLoanMapping.findMany({
        where: {
          OR: [
            { mirrorLoanId: { in: allLoanIds } },
            { originalLoanId: { in: allLoanIds } }
          ]
        },
        select: {
          id: true,
          originalLoanId: true,
          mirrorLoanId: true,
          mirrorCompanyId: true,
          originalCompanyId: true,
          mirrorTenure: true,
          originalTenure: true,
          mirrorInterestRate: true,
          originalInterestRate: true,
          extraEMICount: true,
          mirrorEMIsPaid: true,
          extraEMIsPaid: true,
          originalEMIAmount: true,
          displayColor: true,
          isOfflineLoan: true,
          mirrorCompany: { select: { id: true, name: true, code: true } },
          originalCompany: { select: { id: true, name: true, code: true } }
        }
      });

      // For online loans: fetch mirror loan details separately (FK-less cross-table design)
      const onlineMirrorLoanIds = mirrorLoanMappings
        .filter(m => !m.isOfflineLoan && m.mirrorLoanId)
        .map(m => m.mirrorLoanId as string);
      
      let onlineMirrorLoanDetails: any[] = [];
      if (onlineMirrorLoanIds.length > 0) {
        onlineMirrorLoanDetails = await db.loanApplication.findMany({
          where: { id: { in: onlineMirrorLoanIds } },
          select: {
            id: true, applicationNo: true, status: true, requestedAmount: true,
            disbursedAt: true, createdAt: true,
            company: { select: { id: true, name: true, code: true } },
            customer: { select: { id: true, name: true, phone: true, email: true } },
            sessionForm: { select: { approvedAmount: true, interestRate: true, tenure: true, emiAmount: true } }
          }
        });
      }
      onlineMirrorLoanMap = new Map(onlineMirrorLoanDetails.map(l => [l.id, l]));

      // For offline loans: fetch offline mirror loan details separately
      const offlineMirrorLoanIds = mirrorLoanMappings
        .filter(m => m.isOfflineLoan && m.mirrorLoanId)
        .map(m => m.mirrorLoanId as string);
      
      let offlineMirrorLoanDetails: any[] = [];
      if (offlineMirrorLoanIds.length > 0) {
        offlineMirrorLoanDetails = await db.offlineLoan.findMany({
          where: { id: { in: offlineMirrorLoanIds } },
          select: {
            id: true, loanNumber: true, status: true, loanAmount: true,
            interestRate: true, tenure: true, emiAmount: true,
            displayColor: true, isMirrorLoan: true, customerName: true,
            company: { select: { id: true, name: true, code: true } }
          }
        });
      }
      offlineMirrorLoanMap = new Map(offlineMirrorLoanDetails.map(l => [l.id, l]));

      // Fetch outstanding principal amounts
      const allOnlineIdsForOutstanding = [
        ...onlineLoans.map(l => l.id),
        ...onlineMirrorLoanIds
      ];
      const allOfflineIdsForOutstanding = [
        ...offlineLoans.map(l => l.id),
        ...offlineMirrorLoanIds
      ];

      if (allOnlineIdsForOutstanding.length > 0) {
        const unpaidOnlineEmis = await db.eMISchedule.findMany({
          where: {
            loanApplicationId: { in: allOnlineIdsForOutstanding },
            paymentStatus: { not: 'PAID' }
          },
          select: {
            loanApplicationId: true,
            totalAmount: true,
            paidAmount: true
          }
        });
        unpaidOnlineEmis.forEach(emi => {
          const current = onlineOutstandingMap.get(emi.loanApplicationId) || 0;
          const remaining = (Number(emi.totalAmount) || 0) - (Number(emi.paidAmount) || 0);
          onlineOutstandingMap.set(emi.loanApplicationId, current + remaining);
        });
      }

      if (allOfflineIdsForOutstanding.length > 0) {
        const unpaidOfflineEmis = await db.offlineLoanEMI.findMany({
          where: {
            offlineLoanId: { in: allOfflineIdsForOutstanding },
            paymentStatus: { not: 'PAID' }
          },
          select: {
            offlineLoanId: true,
            totalAmount: true,
            paidAmount: true
          }
        });
        unpaidOfflineEmis.forEach(emi => {
          const current = offlineOutstandingMap.get(emi.offlineLoanId) || 0;
          const remaining = (Number(emi.totalAmount) || 0) - (Number(emi.paidAmount) || 0);
          offlineOutstandingMap.set(emi.offlineLoanId, current + remaining);
        });
      }
    }

    // Create lookup maps
    const mirrorLoanIds = new Set(mirrorLoanMappings.map(m => m.mirrorLoanId).filter(Boolean) as string[]);
    const originalLoanMappings = new Map(mirrorLoanMappings.map(m => [m.originalLoanId, m]));
    const mirrorLoanMappingsByMirrorId = new Map(
      mirrorLoanMappings
        .filter(m => m.mirrorLoanId !== null)
        .map(m => [m.mirrorLoanId!, m] as [string, typeof m])
    );

    // Format online loans
    const formattedOnlineLoans = onlineLoans.map(loan => {
      // Find the next pending/overdue EMI
      const pendingEmis = (loan.emiSchedules || []).filter(
        (e: any) => ['PENDING', 'OVERDUE', 'PARTIALLY_PAID'].includes(e.paymentStatus)
      );
      const nextEmi = pendingEmis[0];

      // Check if this is a mirror loan
      const isMirrorLoan = mirrorLoanIds.has(loan.id);
      const mirrorMapping = isMirrorLoan ? mirrorLoanMappingsByMirrorId.get(loan.id) : originalLoanMappings.get(loan.id);

      return {
        id: loan.id,
        identifier: loan.applicationNo,
        applicationNo: loan.applicationNo,
        loanType: 'ONLINE',
        status: loan.status,
        isMirrorLoan,
        isOriginalMirrorLoan: !isMirrorLoan && mirrorMapping !== undefined,
        // Mirror pair color - same for both original and mirror
        displayColor: mirrorMapping?.displayColor || null,
        // Interest-only loan fields
        isInterestOnlyLoan: loan.isInterestOnlyLoan || false,
        interestOnlyStartDate: loan.interestOnlyStartDate,
        interestOnlyMonthlyAmount: loan.interestOnlyMonthlyAmount,
        loanStartedAt: loan.loanStartedAt,
        totalInterestOnlyPaid: loan.totalInterestOnlyPaid,
        mirrorMapping: mirrorMapping ? {
          id: mirrorMapping.id,
          originalLoanId: mirrorMapping.originalLoanId,
          mirrorLoanId: mirrorMapping.mirrorLoanId,
          mirrorTenure: mirrorMapping.mirrorTenure,
          originalTenure: mirrorMapping.originalTenure,
          mirrorInterestRate: mirrorMapping.mirrorInterestRate,
          originalInterestRate: mirrorMapping.originalInterestRate,
          extraEMICount: mirrorMapping.extraEMICount,
          mirrorEMIsPaid: mirrorMapping.mirrorEMIsPaid,
          extraEMIsPaid: mirrorMapping.extraEMIsPaid,
          originalEMIAmount: mirrorMapping.originalEMIAmount,
          displayColor: mirrorMapping.displayColor,
          isOfflineLoan: mirrorMapping.isOfflineLoan,
          mirrorCompany: mirrorMapping.mirrorCompany,
          originalCompany: mirrorMapping.originalCompany,
          // Embed full mirror loan object for ParallelLoanView
          mirrorLoan: mirrorMapping.mirrorLoanId ? (() => {
            const ml = onlineMirrorLoanMap.get(mirrorMapping.mirrorLoanId);
            if (!ml) return null;
            let mlOutstanding = onlineOutstandingMap.get(ml.id) || 0;
            if (ml.status === 'ACTIVE_INTEREST_ONLY') {
              mlOutstanding = ml.sessionForm?.approvedAmount || ml.requestedAmount || 0;
            }
            return {
              ...ml,
              outstandingAmount: mlOutstanding
            };
          })() : null,
        } : null,
        requestedAmount: loan.requestedAmount,
        approvedAmount: loan.sessionForm?.approvedAmount || loan.requestedAmount,
        outstandingAmount: (() => {
          let outstanding = onlineOutstandingMap.get(loan.id) || 0;
          if (loan.status === 'ACTIVE_INTEREST_ONLY') {
            outstanding = loan.sessionForm?.approvedAmount || loan.requestedAmount || 0;
          }
          return outstanding;
        })(),
        interestRate: loan.sessionForm?.interestRate || 0,
        tenure: loan.sessionForm?.tenure || 0,
        emiAmount: loan.sessionForm?.emiAmount || 0,
        totalAmount: loan.sessionForm?.totalAmount || 0,
        totalInterest: loan.sessionForm?.totalInterest || 0,
        disbursementDate: loan.disbursedAt,
        createdAt: loan.createdAt,
        customer: loan.customer,
        company: loan.company,
        sessionForm: loan.sessionForm,
        emiSchedules: loan.emiSchedules,
        payments: loan.payments || [],
        nextEmi: nextEmi ? {
          id: nextEmi.id,
          dueDate: nextEmi.dueDate,
          amount: nextEmi.totalAmount,
          status: nextEmi.paymentStatus,
          installmentNumber: nextEmi.installmentNumber
        } : null
      };
    });

    // Format offline loans
    const formattedOfflineLoans = offlineLoans.map(loan => {
      // Find the next pending/overdue EMI
      const pendingEmis = (loan.emis || []).filter(
        (e: any) => ['PENDING', 'OVERDUE', 'PARTIALLY_PAID'].includes(e.paymentStatus)
      );
      const nextEmi = pendingEmis[0];
      
      // Check if this is an interest-only loan
      const isInterestOnlyLoan = loan.isInterestOnlyLoan || loan.status === 'INTEREST_ONLY';

      // Check if this is a mirror loan (for offline loans)
      const isMirrorLoan = mirrorLoanIds.has(loan.id) || loan.isMirrorLoan === true;
      const mirrorMapping = isMirrorLoan ? mirrorLoanMappingsByMirrorId.get(loan.id) : originalLoanMappings.get(loan.id);

      return {
        id: loan.id,
        identifier: loan.loanNumber,
        applicationNo: loan.loanNumber,
        loanType: 'OFFLINE',
        status: loan.status,
        isMirrorLoan,
        isOriginalMirrorLoan: !isMirrorLoan && mirrorMapping !== undefined,
        // Mirror pair color - same for both original and mirror
        displayColor: mirrorMapping?.displayColor || loan.displayColor || null,
        isInterestOnlyLoan,
        interestOnlyMonthlyAmount: loan.interestOnlyMonthlyAmount,
        totalInterestOnlyPaid: loan.totalInterestPaid,
        mirrorMapping: mirrorMapping ? {
          id: mirrorMapping.id,
          originalLoanId: mirrorMapping.originalLoanId,
          mirrorLoanId: mirrorMapping.mirrorLoanId,
          mirrorTenure: mirrorMapping.mirrorTenure,
          originalTenure: mirrorMapping.originalTenure,
          mirrorInterestRate: mirrorMapping.mirrorInterestRate,
          originalInterestRate: mirrorMapping.originalInterestRate,
          extraEMICount: mirrorMapping.extraEMICount,
          mirrorEMIsPaid: mirrorMapping.mirrorEMIsPaid,
          extraEMIsPaid: mirrorMapping.extraEMIsPaid,
          originalEMIAmount: mirrorMapping.originalEMIAmount,
          displayColor: mirrorMapping.displayColor,
          isOfflineLoan: mirrorMapping.isOfflineLoan,
          mirrorCompany: mirrorMapping.mirrorCompany,
          originalCompany: mirrorMapping.originalCompany,
          // Embed the offline mirror loan detail for ParallelLoanView
          offlineMirrorLoan: mirrorMapping.mirrorLoanId ? (() => {
            const oml = offlineMirrorLoanMap.get(mirrorMapping.mirrorLoanId);
            if (!oml) return null;
            let omlOutstanding = offlineOutstandingMap.get(oml.id) || 0;
            if (oml.status === 'INTEREST_ONLY') {
              omlOutstanding = oml.loanAmount || 0;
            }
            return {
              ...oml,
              outstandingAmount: omlOutstanding
            };
          })() : null,
        } : null,
        requestedAmount: loan.loanAmount,
        approvedAmount: loan.loanAmount,
        outstandingAmount: (() => {
          let outstanding = offlineOutstandingMap.get(loan.id) || 0;
          if (loan.status === 'INTEREST_ONLY') {
            outstanding = loan.loanAmount || 0;
          }
          return outstanding;
        })(),
        interestRate: loan.interestRate,
        tenure: loan.tenure,
        emiAmount: loan.emiAmount,
        totalAmount: (loan.loanAmount || 0) + (loan.loanAmount * (loan.interestRate / 100) * (loan.tenure / 12)),
        totalInterest: (loan.loanAmount || 0) * (loan.interestRate / 100) * (loan.tenure / 12),
        disbursementDate: loan.disbursementDate,
        createdAt: loan.createdAt,
        customer: loan.customer || {
          id: null,
          name: loan.customerName,
          email: loan.customerEmail,
          phone: loan.customerPhone
        },
        company: loan.company,
        createdBy: loan.createdBy,
        emiSchedules: loan.emis?.map((emi: any) => ({
          id: emi.id,
          installmentNumber: emi.installmentNumber,
          dueDate: emi.dueDate,
          totalAmount: emi.totalAmount,
          principalAmount: emi.principalAmount,
          interestAmount: emi.interestAmount,
          paidAmount: emi.paidAmount,
          paymentStatus: emi.paymentStatus,
          paidDate: emi.paidDate,
          paymentMode: emi.paymentMode,
          penaltyAmount: emi.penaltyAmount,
          daysOverdue: emi.daysOverdue
        })) || [],
        payments: [],
        nextEmi: nextEmi ? {
          id: nextEmi.id,
          dueDate: nextEmi.dueDate,
          amount: nextEmi.totalAmount,
          status: nextEmi.paymentStatus,
          installmentNumber: nextEmi.installmentNumber
        } : null
      };
    });

    // Combine and sort by creation date
    const allLoans = [...formattedOnlineLoans, ...formattedOfflineLoans]
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    // Calculate statistics
    const stats = {
      totalOnline: formattedOnlineLoans.length,
      totalOffline: formattedOfflineLoans.length,
      totalLoans: allLoans.length,
      totalOnlineAmount: formattedOnlineLoans.reduce((sum, l) => sum + l.approvedAmount, 0),
      totalOfflineAmount: formattedOfflineLoans.reduce((sum, l) => sum + l.approvedAmount, 0),
      totalAmount: allLoans.reduce((sum, l) => sum + l.approvedAmount, 0)
    };

    const response = {
      loans: allLoans,
      onlineLoans: formattedOnlineLoans,
      offlineLoans: formattedOfflineLoans,
      stats
    };

    // Cache the result for non-passbook requests (60s — list data is not time-critical)
    if (!includePassbook) {
      cache.set(cacheKey, response, 60_000);
    }

    return NextResponse.json(response);

  } catch (error) {
    console.error('Error fetching all active loans:', error);
    console.error('Error details:', error instanceof Error ? error.message : 'Unknown error');
    console.error('Error stack:', error instanceof Error ? error.stack : 'No stack');
    return NextResponse.json({ 
      error: 'Failed to fetch active loans', 
      details: error instanceof Error ? error.message : 'Unknown error' 
    }, { status: 500 });
  }
}
